// Standalone presentation prototype. All changes are in memory; no requests or credentials are stored.
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',book:'M4 3h13l3 3v15H4z M8 8h8 M8 12h8 M8 16h5',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18',trash:'M4 6h16 M9 3h6 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z'};
const icon = n => `<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
let records=[
 {id:1,title:'把平凡的日子，过得具体一些',type:'日记',date:'2026-09-24',tag:'生活',body:'# 把平凡的日子，过得具体一些\n\n今天在图书馆坐了一下午，终于把毕业设计的思路梳理清楚了。比起急着完成，先把每一步走踏实更重要。\n\n明天下午 14:00—15:00，和导师讨论项目的需求与页面原型。地点在教学楼 302。\n\n周末想找个时间去书店看看，给自己留一点空白。'},
 {id:2,title:'Spring Boot 学习：从请求到响应',type:'笔记',date:'2026-09-23',tag:'学习',body:'# 从请求到响应\n\n- Controller 接收请求\n- Service 处理业务规则\n- Mapper 负责数据访问\n\n把每一层的职责想清楚，代码就更容易理解。'},
 {id:3,title:'傍晚的风，和没读完的书',type:'日记',date:'2026-09-22',tag:'生活',body:'散步的时候，发现路边的桂花开了。\n\n读了几页书，记下一个喜欢的句子：慢慢来，也是在向前走。'},
 {id:4,title:'日迹：第一版功能梳理',type:'笔记',date:'2026-09-21',tag:'毕业设计',body:'# 首版功能\n\n记录生活，整理文字，确认安排。\n\n让 AI 提供建议，让用户做最后的决定。'},
 {id:5,title:'一份暂时放下的草稿',type:'笔记',date:'2026-09-20',tag:'随想',body:'留下一点不成熟的想法。',deleted:true}
];
let events=[{id:1,title:'项目原型设计',date:'2026-09-24',start:'09:00',end:'11:00',place:'图书馆',source:4},{id:2,title:'阅读与学习',date:'2026-09-24',start:'19:00',end:'20:00',place:'自习室'},{id:3,title:'导师讨论',date:'2026-09-25',start:'14:00',end:'15:00',place:'教学楼 302'}];
let current=1, draft=null, dirty=false, month=8,year=2026, filterType='',filterTag='',query='', preview=false,aiSelection=null,aiText='',candidateSource=null;
const app=$('#app'),modal=$('#modal');
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.opacity=0,2800)}
function closeModal(){modal.close()}
function showModal(html){modal.innerHTML=html;modal.showModal()}
const actions = (label,fn) => `<div class="modal-actions"><button onclick="closeModal()">取消</button><button class="primary" onclick="${fn}">${label}</button></div>`;
function confirmAction(title,text,fn){showModal(`<h2>${title}</h2><p>${text}</p>${actions('确认',fn)}`)}
function route(){return location.hash.slice(1)||'home'}
function go(to){if(dirty && ['editor','records'].includes(route()) && to!=='editor'){confirmAction('离开编辑页面？','尚未保存的修改会丢失。',`dirty=false;closeModal();location.hash='${to}'`);return}location.hash=to}
const navs=[['home','home','今日概览'],['records','book','我的笔记'],['calendar','calendar','日程日历'],['trash','trash','回收站'],['settings','settings','账号设置']];
function shell(content){let r=route();app.innerHTML=`<aside class="sidebar app-rail"><a class="brand" href="#home"><span class="brand-mark">迹</span>日迹</a><div class="brand-sub">DAYTRACE</div><div class="nav-group">我的空间</div><nav class="nav">${navs.map(([id,ic,t])=>`<a href="#${id}" onclick="event.preventDefault();go('${id}')" class="${r===id||(r==='editor'&&id==='records')?'active':''}">${icon(ic)}${t}</a>`).join('')}</nav><div class="side-foot">每一天，都有迹可循。<br><span class="eyebrow">A little, every day.</span></div></aside><div class="workspace"><header class="topbar"><span class="small">我的空间 <span style="margin:0 12px;color:#b8c0b7">/</span> ${navs.find(n=>n[0]===r)?.[2]||'编辑记录'}</span><div class="row"><span class="pill">交互原型 · 示例数据</span><span class="avatar">林</span><button class="quiet" onclick="go('login')">退出</button></div></header><main class="main">${content}<div class="footer-note">DAYTRACE · 私人记录空间　 /　 演示日期 2026.09.24 · 北京时间</div></main></div>`}
function heading(title,sub,button=''){return `<div class="row between heading"><div><h1 style="margin-bottom:0">${title}</h1><p>${sub}</p></div>${button}</div>`}
function newButton(){return `<button class="primary" onclick="editRecord()">＋ 写一篇记录</button>`}
function recordCards(){return records.filter(r=>!r.deleted).slice(0,3).map(r=>`<article class="record"><div class="date-stamp">${r.date.slice(8)}<small>SEP</small></div><a href="#editor" onclick="event.preventDefault();editRecord(${r.id})" style="flex:1"><div class="row between"><h3>${esc(r.title)}</h3><span class="small">↗</span></div><p>${esc(r.body.replace(/#/g,'').split('\n').filter(Boolean).slice(1).join(' ').slice(0,42))}…</p><span class="pill">${r.type}</span> <span class="small"># ${esc(r.tag)}</span></a></article>`).join('')}
function home(){shell(`${heading('给今天，留一点痕迹。','2026 年 9 月 24 日，星期四 · 秋日正好',newButton())}<section class="hero"><div class="eyebrow">YOUR EVERYDAY, WELL KEPT</div><h1>从一段文字，到有序的生活。</h1><p>记下此刻的想法，让零散的日常慢慢清晰。<br>那些藏在文字里的计划，也有自己的位置。</p><button onclick="editRecord(1)">继续上次的记录 <span style="margin-left:16px">↗</span></button><div class="hero-art" aria-hidden="true"></div></section><section id="recollection" class="recollection" aria-label="朝花夕拾">${recollectionCard()}</section><div class="stats">${[['留下的记录',records.filter(r=>!r.deleted).length,'篇','book'],['今天的安排',events.filter(e=>e.date==='2026-09-24').length,'项','calendar'],['使用的标签',new Set(records.filter(r=>!r.deleted).map(r=>r.tag)).size,'个','spark']].map(([t,n,u,i])=>`<div class="stat"><div><div class="small">${t}</div><div style="margin-top:7px"><span class="number">${String(n).padStart(2,'0')}</span><span class="small">${u}</span></div></div><div class="stat-icon">${icon(i)}</div></div>`).join('')}</div><div class="columns"><section class="panel"><div class="row between section-title"><h2 style="margin:0">最近的记录</h2><a class="small" href="#records">全部记录 →</a></div>${recordCards()}</section><div><section class="panel"><div class="row between"><h2 style="margin:0">今天的日程</h2><a class="small" href="#calendar">查看日历 ↗</a></div><div class="timeline">${events.filter(e=>e.date==='2026-09-24').map(e=>`<div class="event"><small>${e.all?'全天':e.start+' — '+e.end}</small><h3><a href="#calendar">${esc(e.title)}</a></h3><small>${esc(e.place||'未设置地点')}</small></div>`).join('')}</div><button style="width:100%;border-style:dashed" onclick="eventForm()">＋ 添加日程</button></section><div class="quote">不必把每一天都写得精彩，<br>真实地记下来，就很好。<div class="eyebrow" style="margin-top:13px">MAKE ROOM FOR YOURSELF</div></div></div></div>`)}
function recordsPage(trash=false){if(!trash)return notesWorkspace();let rows=records.filter(r=>!!r.deleted===trash&&(!filterType||r.type===filterType)&&(!filterTag||r.tag===filterTag)&&(!query||(r.title+r.body).toLowerCase().includes(query.toLowerCase())));shell(`${heading(trash?'回收站':'我的笔记',trash?'暂时放下的文字，也可以重新找回。':'日记与笔记，收好生活里的每一页。',trash?'':newButton())}<section class="panel"><div class="filters"><input class="search" id="search" aria-label="搜索记录" placeholder="搜索标题或正文…" value="${esc(query)}" onkeydown="if(event.key==='Enter')searchRecords()"><select id="filterType" aria-label="记录类型"><option value="">全部类型</option>${['日记','笔记'].map(t=>`<option ${filterType===t?'selected':''}>${t}</option>`).join('')}</select><select id="filterTag" aria-label="标签筛选"><option value="">全部标签</option>${[...new Set(records.map(r=>r.tag))].map(t=>`<option ${filterTag===t?'selected':''}>${esc(t)}</option>`).join('')}</select><button class="primary" onclick="searchRecords()">查询</button><button onclick="query='';filterType='';filterTag='';render()">重置</button></div>${trash?'<div class="notice">记录不会自动清理。删除来源记录不会删除已创建的日程。</div>':''}<div class="table-wrap"><table><thead><tr><th>标题</th><th>类型</th><th>记录日期</th><th>标签</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.title)}</td><td><span class="pill ${r.type==='笔记'?'warm':''}">${r.type}</span></td><td class="small">${r.date}</td><td class="small"># ${esc(r.tag)}</td><td>${trash?`<button class="quiet" onclick="restore(${r.id})">恢复</button> <button class="quiet danger" onclick="removeRecord(${r.id},true)">永久删除</button>`:`<button class="quiet" onclick="editRecord(${r.id})">打开</button> <button class="quiet danger" onclick="removeRecord(${r.id})">删除</button>`}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':`<div class="empty">${trash?'回收站中没有匹配的记录':'没有找到记录，换个关键词试试。'}</div>`}<div class="row between small" style="margin-top:22px"><span>共 ${rows.length} 篇记录</span><span>第 1 页 / 共 1 页</span></div></section>`)}
function searchRecords(){query=$('#search').value;filterType=$('#filterType').value;filterTag=$('#filterTag').value;render()}
function restore(id){records.find(r=>r.id===id).deleted=false;render();toast('记录已恢复到我的笔记')}
function removeRecord(id,forever=false){confirmAction(forever?'永久删除这篇记录？':'将记录移入回收站？',forever?'永久删除后无法恢复。已创建的日程仍会保留。':'你可以在回收站中恢复，关联日程不受影响。',`completeRemove(${id},${forever})`)}
function completeRemove(id,forever){if(forever)records=records.filter(r=>r.id!==id);else records.find(r=>r.id===id).deleted=true;closeModal();render();toast(forever?'示例记录已永久删除':'已移入回收站')}
function editRecord(id){if(dirty){confirmAction('切换笔记？','尚未保存的修改会丢失。',"dirty=false;closeModal();editRecord("+(id||'')+")" );return}current=id||null;draft=id?{...records.find(r=>r.id===id)}:{title:'',body:'',type:'笔记',date:'2026-09-24',tag:'随想'};dirty=false;preview=!!id;location.hash='records';notesWorkspace()}
function syncDraft(){if(!$('#recordTitle'))return;Object.assign(draft,{title:$('#recordTitle').value,body:$('#body')?$('#body').value:draft.body,type:$('#recordType').value,date:$('#recordDate').value,tag:$('#recordTag').value})}
function markdown(text){return esc(text).split('\n').map(l=>l.startsWith('# ')?`<h2>${l.slice(2)}</h2>`:l.startsWith('- ')?`• ${l.slice(2)}`:l.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')).join('\n')}
function saveRecord(silent=false){syncDraft();if(!draft.title.trim()||!draft.body.trim()||!draft.date){toast('请填写标题、正文和记录日期');return false}if(current)Object.assign(records.find(r=>r.id===current),draft);else{current=Date.now();records.unshift({...draft,id:current})}dirty=false;if(!silent)toast('记录已保存到当前演示会话');return true}
function writeAI(mode){syncDraft();let body=$('#body');aiSelection=mode==='polish'&&body?{start:body.selectionStart,end:body.selectionEnd}:null;if(mode==='polish'&&(!aiSelection||aiSelection.start===aiSelection.end)){toast('请先在正文中选中需要润色的文字');return}if(!draft.body.trim()){toast('请先输入一些文字或要点');return}aiText=mode==='polish'?'今天在图书馆度过了安静而充实的一下午，毕业设计的思路也渐渐清晰。':'# 把日常整理成一页\n\n今天梳理了毕业设计的思路，也给自己留出了阅读的时间。\n\n明天 14:00—15:00，去教学楼 302 与导师讨论项目需求和页面原型。\n\n慢慢来，把每一步走踏实。';showModal(`<div class="row between"><h2>${mode==='polish'?'润色建议':'整理成文'}</h2><span class="pill">固定样例</span></div><p>以下为交互示意，与你输入的内容无关。采用前请核对。</p><div class="candidate" style="white-space:pre-wrap">${esc(aiText)}</div><div class="notice">${mode==='polish'?'只替换此前选中的文字。':'采用后替换当前正文；尚需手动保存记录。'}</div>${actions('采用建议','applyAI()')}`)}
function applyAI(){draft.body=aiSelection?draft.body.slice(0,aiSelection.start)+aiText+draft.body.slice(aiSelection.end):aiText;dirty=true;closeModal();preview=false;editor();toast('建议已采用，请保存记录')}
function extractAI(){if(!saveRecord(true))return;candidateSource=current;showModal(`<h2>确认候选日程</h2><p>01 识别安排　→　<strong>02 核对与补充</strong>　→　03 加入日历</p><div class="notice">固定样例：以 2026-09-24 日记为基准，“明天”是 2026-09-25。笔记应以操作当天为基准；此原型不解析任意输入。</div><label>演示结果<select onchange="candidateState(this.value)"><option value="normal">正常提取</option><option value="empty">未识别到日程</option><option value="error">AI 暂时不可用</option></select></label><div id="candidates"><div class="candidate"><span class="pill warm">可能重复 · 已有“导师讨论”</span><label>安排标题<input id="candidateTitle" value="与导师讨论项目原型"></label><div class="row"><label style="flex:1">具体日期<input id="candidateDate" type="date" value="2026-09-25"></label><label>开始<input id="candidateStart" type="time" value="14:00"></label><label>结束<input id="candidateEnd" type="time" value="15:00"></label></div><p class="small" style="margin-top:12px">与“导师讨论”时间重叠；仍可确认添加。</p><button class="primary" onclick="addCandidate()">确认这一项并入表</button></div><div class="candidate"><span class="pill warm">待补充</span><h3 style="margin-top:12px">周末去书店</h3><p>“周末找个时间”不够明确，需要补充日期与时间。</p><button onclick="closeModal();eventForm(null,'', '去书店',candidateSource)">补充后确认</button></div></div><div class="modal-actions"><button onclick="closeModal()">完成 / 返回记录</button></div>`)}
function candidateState(v){if(v==='normal'){closeModal();extractAI();return}$('#candidates').innerHTML=`<div class="empty">${v==='empty'?'没有识别到明确安排，可继续写作或手动添加日程。':'AI 暂时不可用，原文已保留。你仍可管理记录与日程。'}</div><button onclick="closeModal();extractAI()">手动重试</button>`}
function addCandidate(){let title=$('#candidateTitle').value,date=$('#candidateDate').value,start=$('#candidateStart').value,end=$('#candidateEnd').value;if(!title.trim()||!date||!start||!end||end<=start){toast('请补全日期、标题和有效起止时间');return}events.push({id:Date.now(),title,date,start,end,place:'教学楼 302',source:candidateSource});let c=$('#candidateTitle').closest('.candidate');c.innerHTML='<span class="pill">已加入日历</span><p style="margin:12px 0 0">这一项已确认，不会重复添加。</p>';toast('候选日程已确认入表')}
function calendarPage(){const days=new Date(year,month+1,0).getDate(),offset=(new Date(year,month,1).getDay()+6)%7;let cells=Array(offset).fill('<div class="day" style="background:#fafbf8"></div>');for(let d=1;d<=days;d++){let date=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;cells.push(`<div class="day ${date==='2026-09-24'?'today':''}" role="button" tabindex="0" aria-label="${date} 添加日程" onclick="eventForm(null,'${date}')" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();eventForm(null,'${date}')}"><span class="day-num">${d}</span>${events.filter(e=>e.date===date).map(e=>`<button class="cal-event" onclick="event.stopPropagation();eventForm(${e.id})">${e.all?'全天':e.start} ${esc(e.title)}</button>`).join('')}</div>`)}shell(`${heading('让每个安排，各得其所。','从文字出发，也可以在这里直接安排。',`<button class="primary" onclick="eventForm()">＋ 新建日程</button>`)}<section class="panel calendar-panel"><div class="row between wrap" style="padding:5px 6px 24px"><div class="row"><h2 style="margin:0;font-size:22px">${year} 年 ${month+1} 月</h2><span class="pill">月视图</span></div><div class="row"><button aria-label="上个月" onclick="changeMonth(-1)">‹</button><button onclick="year=2026;month=8;render()">今天</button><button aria-label="下个月" onclick="changeMonth(1)">›</button></div></div><div class="calendar">${['一','二','三','四','五','六','日'].map(d=>`<div class="weekday">周${d}</div>`).join('')}${cells.join('')}</div><div class="row between small" style="margin-top:20px"><span>点击日期添加 · 点击安排查看详情</span><span>北京时间 UTC+8</span></div></section><div class="notice">时间重叠只提示、不阻止保存。全天事项不参与时段冲突判定。已确认的日程独立于来源记录管理。</div>`)}
function changeMonth(n){month+=n;if(month<0){month=11;year--}if(month>11){month=0;year++}render()}
function eventForm(id,date='2026-09-24',title='',source=null){const e=events.find(e=>e.id===id)||{title,date,start:'09:00',end:'10:00',place:'',source};showModal(`<h2>${id?'日程详情':'新建日程'}</h2><p>把时间留给重要的事。</p><form id="eventForm"><label>安排标题<input id="eventTitle" value="${esc(e.title)}" required></label><label>日期<input id="eventDate" type="date" value="${e.date}" required></label><label><input type="checkbox" id="allDay" ${e.all?'checked':''} onchange="document.querySelectorAll('.time-input').forEach(i=>i.disabled=this.checked);conflicts(${id||0})"> 全天事项</label><div class="row"><label style="flex:1">开始时间<input class="time-input" id="eventStart" type="time" value="${e.start}" ${e.all?'disabled':''}></label><label style="flex:1">结束时间<input class="time-input" id="eventEnd" type="time" value="${e.end}" ${e.all?'disabled':''}></label></div><label>地点（选填）<input id="eventPlace" value="${esc(e.place)}"></label>${e.source?`<div class="notice">来源记录：${esc(records.find(r=>r.id===e.source)?.title||'记录已永久删除')}<br>修改本日程不会更改原文。</div>`:''}<div id="conflict" class="notice" hidden></div><div id="formError" class="error" role="alert"></div><div class="modal-actions">${id?`<button type="button" class="danger" onclick="closeModal();confirmAction('删除这项日程？','来源记录将保留。','deleteEvent(${id})')">删除日程</button>`:''}<button type="button" onclick="closeModal()">取消</button><button class="primary" type="submit">保存日程</button></div></form>`);$('#eventForm').oninput=()=>conflicts(id);$('#eventForm').onsubmit=ev=>{ev.preventDefault();saveEvent(id,e.source)};conflicts(id)}
function conflicts(id){let date=$('#eventDate').value,start=$('#eventStart').value,end=$('#eventEnd').value;let list=events.filter(e=>e.id!==id&&e.date===date&&!e.all&&!$('#allDay').checked&&start<e.end&&end>e.start);$('#conflict').hidden=!list.length;$('#conflict').textContent='时间重叠：'+list.map(e=>e.title).join('、')+'。仍可保存，请核对安排。'}
function saveEvent(id,source){let e={id:id||Date.now(),title:$('#eventTitle').value.trim(),date:$('#eventDate').value,start:$('#eventStart').value,end:$('#eventEnd').value,all:$('#allDay').checked,place:$('#eventPlace').value,source};if(!e.title||!e.date||(!e.all&&(!e.start||!e.end||e.end<=e.start))){$('#formError').textContent='请填写标题与日期，结束时间必须晚于开始时间。';return}if(id)Object.assign(events.find(x=>x.id===id),e);else events.push(e);closeModal();render();toast('日程已保存')}
function deleteEvent(id){events=events.filter(e=>e.id!==id);closeModal();render();toast('日程已删除，来源记录保留')}
function settings(){shell(`${heading('账号设置','照顾好你的私人记录空间。')}<section class="panel"><h2>修改密码</h2><p class="small">原型仅演示表单与校验；请勿输入真实密码。原密码示例：demo1234。</p><form class="form" id="passwordForm"><label>原密码</label><input type="password" aria-label="原密码" id="oldPassword" required autocomplete="off"><label>新密码</label><input type="password" aria-label="新密码" id="newPassword" required minlength="8" autocomplete="off"><label>确认新密码</label><input type="password" aria-label="确认新密码" id="confirmPassword" required autocomplete="off"><div class="error" id="passwordError" role="alert"></div><button class="primary">保存修改</button></form></section>`);$('#passwordForm').onsubmit=e=>{e.preventDefault();let error=$('#oldPassword').value!=='demo1234'?'原密码不正确，请重新输入。':$('#newPassword').value!==$('#confirmPassword').value?'两次输入的密码不一致。':$('#newPassword').value===$('#oldPassword').value?'新密码不能与原密码相同。':'';if(error){$('#passwordError').textContent=error;return}go('login');toast('修改流程演示完成，请重新登录；没有保存任何密码')}}
function auth(register=false){app.innerHTML=`<div class="auth"><section class="auth-art"><div class="brand"><span class="brand-mark">迹</span>日迹 <span class="eyebrow">DAYTRACE</span></div><h1>把日子写下来。<br>把生活理清楚。</h1><p>收藏细小的感受，也安放下一步的计划。<br>这里，是只属于你的记录空间。</p><div class="quote" style="margin-top:40px">每一天，都有迹可循。</div></section><section class="auth-form"><form class="form" id="authForm"><span class="eyebrow">YOUR PRIVATE CORNER</span><h1 style="margin:12px 0">${register?'开启你的日迹':'欢迎回来'}</h1><p>${register?'从今天开始，留下生活的痕迹。':'一页新的日常，等你继续。'}</p><div class="notice">演示表单，不连接账号系统。请勿输入真实凭据。</div><label>用户名</label><input aria-label="用户名" required placeholder="输入演示用户名" autocomplete="off"><label>密码</label><input aria-label="密码" type="password" required minlength="8" id="authPassword" placeholder="至少 8 位演示字符" autocomplete="off">${register?'<label>确认密码</label><input type="password" aria-label="确认密码" id="authConfirm" required autocomplete="off">':''}<div class="error" id="authError" role="alert"></div><button class="primary">${register?'注册并进入（演示）':'登录（演示）'}</button><button type="button" class="quiet" onclick="go('${register?'login':'register'}')">${register?'已有账号？返回登录':'还没有账号？注册日迹'} →</button><button type="button" class="quiet" onclick="go('home')">直接浏览原型</button></form></section></div>`;$('#authForm').onsubmit=e=>{e.preventDefault();if(register&&$('#authPassword').value!==$('#authConfirm').value){$('#authError').textContent='两次输入的密码不一致。';return}go('home');toast('已进入示例空间；此处不验证或保存账号')}}
function render(){const r=route();if(r==='login'||r==='register')return auth(r==='register');if(r==='home')home();else if(r==='records'||r==='trash')recordsPage(r==='trash');else if(r==='editor')editor();else if(r==='calendar')calendarPage();else if(r==='settings')settings();else home()}
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});render();


function editor(){notesWorkspace()}
function notesWorkspace(){
  if(!draft || (current && !records.some(r=>r.id===current&&!r.deleted))){let first=records.find(r=>!r.deleted);current=first?.id||null;draft=first?{...first}:{title:'',body:'',type:'笔记',date:'2026-09-24',tag:'随想'};preview=!!first;dirty=false}
  shell(`<div class="notes-layout"><aside class="notes-list"><div class="row between notes-list-heading"><h2>我的笔记</h2><button class="quiet" title="新建笔记" aria-label="新建笔记" onclick="editRecord()">＋</button></div><input id="noteSearch" aria-label="搜索笔记" placeholder="⌕  搜索笔记" value="${esc(query)}" oninput="query=this.value;refreshNoteList()"><div class="row note-filters"><select aria-label="笔记类型筛选" onchange="filterType=this.value;refreshNoteList()"><option value="">全部类型</option>${['日记','笔记'].map(t=>`<option ${filterType===t?'selected':''}>${t}</option>`).join('')}</select><span id="noteCount" class="small"></span></div><div id="noteItems"></div><div class="notes-list-foot">私人的想法，安心放在这里。</div></aside><section class="note-workspace"><div class="note-tools"><div class="row"><button class="quiet" onclick="toggleOutline()" title="正文目录" aria-label="正文目录">☷</button><span class="tool-divider"></span><button class="quiet" onclick="formatNote('heading')" title="插入标题">H₁</button><button class="quiet" onclick="formatNote('bold')" title="加粗选中文本"><b>B</b></button><button class="quiet" onclick="formatNote('list')" title="插入列表">☷ 列表</button><span class="tool-divider"></span><button class="quiet" onclick="syncDraft();preview=!preview;notesWorkspace()">${preview?'编辑正文':'阅读视图'}</button></div><div class="row"><button class="quiet" onclick="saveNote()">保存</button><button class="quiet danger" ${current?'':'disabled'} onclick="removeRecord(${current})" aria-label="删除当前笔记">${icon('trash')}</button><button class="note-ai" onclick="showNoteAI()">${icon('spark')} AI 写作</button></div></div><div class="note-scroll"><aside id="noteOutline" class="note-outline" hidden></aside><article class="note-paper" oninput="dirty=true;syncDraft();updateNoteStatus()"><input id="recordTitle" class="editor-title" aria-label="笔记标题" placeholder="无标题笔记" value="${esc(draft.title)}"><div class="row wrap note-meta"><select id="recordType" aria-label="记录类型" onchange="$('#recordDate').disabled=this.value==='笔记'"><option ${draft.type==='笔记'?'selected':''}>笔记</option><option ${draft.type==='日记'?'selected':''}>日记</option></select><input id="recordDate" type="date" aria-label="记录日期" value="${draft.date}" ${draft.type==='笔记'?'disabled':''}><span class="small">#</span><input id="recordTag" aria-label="记录标签" value="${esc(draft.tag)}" placeholder="添加标签"></div>${preview?`<div class="note-reading">${noteMarkdown(draft.body)}</div>`:`<textarea id="body" class="note-textarea" aria-label="笔记正文" placeholder="写下想法，或从一个简单的标题开始…">${esc(draft.body)}</textarea>`}</article></div><footer class="note-status"><span>Markdown 笔记 · 示例内容，仅当前会话保留</span><span id="noteSaveStatus">${draft.body.length} 字 · ${dirty?'未保存':'已保存'}</span></footer></section></div>`);
  $('.workspace').classList.add('notes-mode');$('.sidebar').classList.add('notes-rail');refreshNoteList();
}
function refreshNoteList(){const rows=records.filter(r=>!r.deleted&&(!filterType||r.type===filterType)&&(!query||(r.title+r.body).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));$('#noteCount').textContent=rows.length+' 篇';let group='';$('#noteItems').innerHTML=rows.map(r=>{const g=r.date>='2026-09-18'?'过去 7 天':r.date>='2026-08-26'?'过去 30 天':'更早';const label=group!==g?`<div class="note-group">${g}</div>`:'';group=g;return label+`<button class="note-item ${r.id===current?'selected':''}" onclick="editRecord(${r.id})"><strong>${esc(r.title)}</strong><span>${r.date.slice(5).replace('-','/')} · ${esc(r.body.replace(/^#+\s*/gm,'').replace(/\n+/g,' ').slice(0,90))}</span><small>${r.type} · #${esc(r.tag)}</small></button>`}).join('')||'<div class="empty">没有匹配的笔记</div>'}
function updateNoteStatus(){const el=$('#noteSaveStatus');if(el)el.textContent=draft.body.length+' 字 · '+(dirty?'未保存':'已保存')}
function saveNote(){if(saveRecord()){refreshNoteList();updateNoteStatus()}}
function noteMarkdown(text){return esc(text).split('\n').map((l,i)=>{if(l==='# '+esc(draft.title))return '';if(/^#{1,3} /.test(l)){const level=Math.min(l.match(/^#+/)[0].length+1,4);return `<h${level} id="note-heading-${i}">${l.replace(/^#+ /,'')}</h${level}>`}if(l.startsWith('- '))return `<div class="note-bullet">${l.slice(2).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')}</div>`;return l?`<p>${l.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')}</p>`:'<div class="note-space"></div>'}).join('')}
function formatNote(type){syncDraft();if(preview){preview=false;notesWorkspace()}const field=$('#body'),a=field.selectionStart,b=field.selectionEnd;const selected=field.value.slice(a,b);let insert=type==='bold'?'**'+(selected||'加粗文字')+'**':(a>0&&field.value[a-1]!=='\n'?'\n':'')+(type==='heading'?'# ':'- ')+(selected||(type==='heading'?'新的标题':'列表事项'));field.setRangeText(insert,a,b,'select');field.focus();dirty=true;syncDraft();updateNoteStatus()}
function toggleOutline(){syncDraft();if(!preview){preview=true;notesWorkspace()}const panel=$('#noteOutline');panel.hidden=!panel.hidden;panel.innerHTML='<strong>目录</strong>'+draft.body.split('\n').map((l,i)=>/^#{1,3} /.test(l)&&l!=='# '+draft.title?`<a href="#" onclick="event.preventDefault();document.getElementById('note-heading-${i}').scrollIntoView({behavior:'smooth',block:'start'})">${esc(l.replace(/^#+ /,''))}</a>`:'').join('');if(!panel.querySelector('a'))panel.innerHTML+='<p class="small">添加 Markdown 标题后显示目录。</p>'}
function showNoteAI(){syncDraft();const field=$('#body');if(field)field.focus();showModal(`<h2>AI 写作助手</h2><p>只处理本次主动提交的文字，先预览，再采用。</p><div class="note-ai-options"><button onclick="closeModal();writeAI('organize')">${icon('spark')} 整理成文</button><button onclick="closeModal();writeAI('polish')">润色选中文本</button><button onclick="closeModal();extractAI()">${icon('calendar')} 提取候选日程</button></div><div class="notice">固定样例演示，不发送文本或调用真实模型。润色需先进入编辑正文并选中文字。</div><div class="modal-actions"><button onclick="closeModal()">返回笔记</button></div>`)}



// Use the same reference day as the rest of this fixed-date prototype.
function recollectionCandidates(){return records.filter(r=>!r.deleted && r.date<'2026-09-24')}
function recollectionCard(change=false){
  const candidates=recollectionCandidates();
  let chosen=candidates.find(r=>r.id===recollectionCard.currentId);
  if(change||!chosen){const pool=candidates.filter(r=>r.id!==chosen?.id);chosen=pool.length?pool[Math.floor(Math.random()*pool.length)]:chosen;recollectionCard.currentId=chosen?.id}
  return `<div class="recollection-label"><span class="eyebrow">A PAGE FROM THE PAST</span><h2>朝花夕拾</h2><p>翻开旧日的一页，与过去的自己重逢。</p></div>${chosen?`<div class="recollection-content" aria-live="polite"><div class="row wrap small"><time>${chosen.date.replaceAll('-',' / ')}</time><span>· ${chosen.type}</span><span># ${esc(chosen.tag)}</span></div><h3>${esc(chosen.title)}</h3><p>${esc(chosen.body.replace(/^#{1,6}\s+.*$/gm,'').replace(/[*\x60]/g,'').replace(/\s+/g,' ').trim().slice(0,100))}</p></div><div class="recollection-actions"><button class="primary" onclick="editRecord(${chosen.id})">阅读全文 ↗</button><button class="quiet" onclick="changeRecollection()" ${candidates.length<2?'disabled':''}>换一篇 ↻</button>${candidates.length<2?'<small>目前只有这一篇往日笔记</small>':''}</div>`:'<div class="recollection-content"><h3>往日的故事，会在这里重逢。</h3><p>还没有可回顾的往日笔记。写下今天，留给未来的自己。</p></div><button onclick="editRecord()">写一篇笔记 ↗</button>'}`;
}
function changeRecollection(){const card=$('#recollection');if(card)card.innerHTML=recollectionCard(true)}
